package com.greatleyposhley.professy.collaboration;

import com.greatleyposhley.professy.entities.*;
import com.greatleyposhley.professy.repositories.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import tools.jackson.databind.ObjectMapper;
import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.sql.Statement;
import java.time.LocalDate;
import java.io.*;
import java.util.zip.*;
import static com.greatleyposhley.professy.collaboration.WorkAccess.number;
import static com.greatleyposhley.professy.collaboration.DeliveryRules.*;

/** Organization-scoped service catalog, architecture and support-to-delivery workflow. */
@RestController @RequestMapping("/api/operations")
public class DeliveryOperations {
 final WorkAccess access;final ObjectMapper json;final WorkspaceAgents agents;final IssuesRepository issues;
 final ProjectsRepository projects;final ReleaseRepository releases;final Path storage;
 public DeliveryOperations(WorkAccess access,ObjectMapper json,WorkspaceAgents agents,IssuesRepository issues,ProjectsRepository projects,ReleaseRepository releases,@Value("${app.attachments.directory:./.runtime/attachments}")String directory){this.access=access;this.json=json;this.agents=agents;this.issues=issues;this.projects=projects;this.releases=releases;storage=Path.of(directory).toAbsolutePath().normalize();}
 long org(){return access.actor().getOrgId();}
 void manage(){access.require("PROJECTS.UPDATE");}
 public long insert(String sql,Object... args){var key=new GeneratedKeyHolder();access.jdbc.update(c->{var s=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS);for(int i=0;i<args.length;i++)s.setObject(i+1,args[i]);return s;},key);return Objects.requireNonNull(key.getKey()).longValue();}
 Map<String,Object> service(long id){var rows=access.jdbc.queryForList("SELECT * FROM delivery_services WHERE id=? AND org_id=?",id,org());if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Service not found");access.project(number(rows.getFirst().get("project_id")));return rows.getFirst();}
 @GetMapping("/services") public Object services(@RequestParam long projectId){access.project(projectId);var rows=access.jdbc.queryForList("SELECT s.*,COALESCE(a.display_name,CONCAT_WS(' ',u.first_name,u.last_name)) AS ownerName FROM delivery_services s LEFT JOIN workspace_actors a ON s.owner_type='AGENT' AND a.id=s.owner_id LEFT JOIN user_account u ON s.owner_type='HUMAN' AND u.id=s.owner_id WHERE s.org_id=? AND s.project_id=? ORDER BY s.name",org(),projectId);for(var s:rows)s.put("releases",access.jdbc.queryForList("SELECT r.id,r.name,r.version_number,r.status,r.release_date FROM delivery_release_services l JOIN releases r ON r.id=l.release_id WHERE l.org_id=? AND l.service_id=? ORDER BY r.created_at DESC LIMIT 10",org(),s.get("id")));return rows;}
 @PostMapping("/services") @Transactional public Object createService(@RequestBody Map<String,Object> b){manage();long project=number(b.get("projectId"));access.project(project);long id=insert("INSERT INTO delivery_services(org_id,project_id,name,description,kind,environment,repository_url,owner_id,owner_type,port,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)",org(),project,required(b.get("name"),160),text(b.get("description"),4000),choice(b.get("kind"),Set.of("API","UI","WORKER","DATABASE","QUEUE","EXTERNAL")),required(b.get("environment"),40),repository(b.get("repositoryUrl")),owner(b,project),choice(b.getOrDefault("ownerType","HUMAN"),Set.of("HUMAN","AGENT")),port(b.get("port")),access.actor().getId());return service(id);}
 @PutMapping("/services/{id}") @Transactional public Object updateService(@PathVariable long id,@RequestBody Map<String,Object>b){manage();var s=service(id);access.jdbc.update("UPDATE delivery_services SET name=?,description=?,kind=?,environment=?,repository_url=?,owner_id=?,owner_type=?,port=?,updated_at=CURRENT_TIMESTAMP(6) WHERE id=? AND org_id=?",required(b.get("name"),160),text(b.get("description"),4000),choice(b.get("kind"),Set.of("API","UI","WORKER","DATABASE","QUEUE","EXTERNAL")),required(b.get("environment"),40),repository(b.get("repositoryUrl")),owner(b,number(s.get("project_id"))),choice(b.getOrDefault("ownerType","HUMAN"),Set.of("HUMAN","AGENT")),port(b.get("port")),id,org());return service(id);}
 private Object owner(Map<String,Object>b,long project){long id=number(b.get("ownerId"));if(id==0)return null;if("AGENT".equals(b.get("ownerType"))){agents.row(id);if(!agents.projects(id).contains(project))throw new IllegalArgumentException("Owner agent must belong to this project");}else if(access.jdbc.queryForObject("SELECT COUNT(*) FROM user_account WHERE id=? AND org_id=? AND is_active=1",Integer.class,id,org())!=1)throw new IllegalArgumentException("Choose an active owner in this organization");return id;}
 private Object port(Object value){long p=number(value);if(p<0||p>65535)throw new IllegalArgumentException("Port must be 1–65535");return p==0?null:p;}
 private String repository(Object value){String s=text(value,500);if(!s.isBlank()&&!s.matches("https?://[^\\s]+"))throw new IllegalArgumentException("Use an HTTP or HTTPS repository URL");return s;}
 @PostMapping("/services/import-local") @Transactional public Object importLocal(@RequestBody Map<String,Object>b){manage();long project=number(b.get("projectId"));access.project(project);String[][] inventory={{"Astra core","API","8080"},{"Notifications","WORKER","8082"},{"Email delivery","WORKER","8083"},{"Relay conversations","API","8084"},{"Relay realtime","API","8085"},{"Access identity","API","8086"},{"Folio documents","API","8087"},{"Tempo calendar","API","8088"},{"Grid sheets","API","8089"},{"Prism slides","API","8090"},{"Gather meetings","API","8091"},{"Local coding agent","WORKER","8092"},{"Forge repositories","API","8093"},{"Instru telemetry","API","8094"},{"Post mail","API","8095"},{"Kafka","QUEUE","9092"},{"MySQL","DATABASE","3306"}};
  for(var s:inventory)access.jdbc.update("INSERT IGNORE INTO delivery_services(org_id,project_id,name,description,kind,environment,port,created_by) VALUES(?,?,?,'Local suite service inventory; availability is not inferred.',?,'local',?,?)",org(),project,s[0],s[1],Integer.parseInt(s[2]),access.actor().getId());return services(project);}
 Set<Long> serviceIds(long project){return new HashSet<>(access.jdbc.queryForList("SELECT id FROM delivery_services WHERE org_id=? AND project_id=?",Long.class,org(),project));}
 @GetMapping("/architecture") public Object architecture(@RequestParam long projectId){access.project(projectId);var rows=access.jdbc.queryForList("SELECT * FROM delivery_architectures WHERE org_id=? AND project_id=?",org(),projectId);return rows.isEmpty()?Map.of("revision",0,"graph",Map.of("nodes",List.of(),"edges",List.of())):Map.of("revision",rows.getFirst().get("revision"),"graph",json.readValue(rows.getFirst().get("graph_json").toString(),Map.class));}
 @PutMapping("/architecture") @Transactional public Object saveArchitecture(@RequestParam long projectId,@RequestBody Map<String,Object>b){manage();access.project(projectId);var graph=DeliveryRules.graph(b.get("graph"),serviceIds(projectId));long revision=number(b.get("revision"));if(revision==0){try{access.jdbc.update("INSERT INTO delivery_architectures(org_id,project_id,graph_json,updated_by) VALUES(?,?,?,?)",org(),projectId,json.writeValueAsString(graph),access.actor().getId());}catch(org.springframework.dao.DuplicateKeyException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Architecture changed. Reload before saving.");}}else if(access.jdbc.update("UPDATE delivery_architectures SET graph_json=?,revision=revision+1,updated_by=?,updated_at=CURRENT_TIMESTAMP(6) WHERE org_id=? AND project_id=? AND revision=?",json.writeValueAsString(graph),access.actor().getId(),org(),projectId,revision)!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"Architecture changed. Reload before saving.");return architecture(projectId);}
 @GetMapping("/agents") public Object configurations(){access.require("AGENTS.READ");return access.jdbc.queryForList("SELECT a.id,a.display_name AS name,a.status,p.designation,p.instructions,p.description,p.model AS preferredModel,c.enabled,c.model,c.skills_json,c.review_required,c.last_seen FROM workspace_actors a JOIN workspace_agent_profiles p ON p.actor_id=a.id LEFT JOIN delivery_agent_config c ON c.agent_id=a.id WHERE a.org_id=? AND a.actor_type='AGENT' ORDER BY a.display_name",org()).stream().map(row->{row.put("skills",row.get("skills_json")==null?List.of():json.readValue(row.remove("skills_json").toString(),List.class));row.put("projectIds",agents.projects(number(row.get("id"))));row.put("executionDefaults",RuntimeSkills.defaults(access.jdbc,json,org(),number(row.get("id"))));row.put("worker",RuntimeSkills.report(access.jdbc,json,org(),number(row.get("id"))));row.put("sandbox",Map.of("network",false,"hostFiles",false,"checkSeconds",30,"maxRepairs",1,"workflow","isolated-python"));return row;}).toList();}
 @GetMapping("/agent-skills") public Object skillCatalog(){access.require("AGENTS.READ");return RuntimeSkills.CATALOG;}
 @PutMapping("/agents/{id}") @Transactional public Object configure(@PathVariable long id,@RequestBody Map<String,Object>b){access.requireAdmin();agents.row(id);Object raw=b.get("skills");if(!(raw instanceof List<?> skills)||skills.isEmpty()||!SKILLS.containsAll(skills))throw new IllegalArgumentException("Choose supported runtime skills");String model=required(b.get("model"),120);if(!model.matches("[A-Za-z0-9._:/-]+"))throw new IllegalArgumentException("Invalid local model name");access.jdbc.update("INSERT INTO delivery_agent_config(agent_id,org_id,enabled,model,skills_json,updated_by) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),model=VALUES(model),skills_json=VALUES(skills_json),updated_by=VALUES(updated_by),updated_at=CURRENT_TIMESTAMP(6)",id,org(),Boolean.TRUE.equals(b.get("enabled")),model,json.writeValueAsString(skills),access.actor().getId());if(b.containsKey("executionDefaults")){var defaults=(Map<String,Object>)b.get("executionDefaults");var validated=new LinkedHashMap<String,Object>();if(!defaults.isEmpty()&&number(defaults.get("repositoryId"))>0){var candidate=new LinkedHashMap<String,Object>(defaults);candidate.put("acceptanceCriteria","Ticket-specific acceptance criteria required before running");validated.putAll(TicketExecution.validate(candidate));validated.remove("acceptanceCriteria");}access.jdbc.update("INSERT INTO agent_execution_defaults(agent_id,org_id,defaults_json,updated_by) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE defaults_json=VALUES(defaults_json),updated_by=VALUES(updated_by),updated_at=CURRENT_TIMESTAMP(6)",id,org(),json.writeValueAsString(validated),access.actor().getId());}return configurations();}
 @PostMapping("/agents/{id}/enroll") @Transactional public Object enroll(@PathVariable long id){access.requireAdmin();agents.row(id);if(access.jdbc.queryForObject("SELECT COUNT(*) FROM delivery_agent_config WHERE agent_id=? AND org_id=?",Integer.class,id,org())!=1)throw new IllegalArgumentException("Save the agent runtime configuration first");String secret=UUID.randomUUID().toString()+UUID.randomUUID();access.jdbc.update("UPDATE delivery_agent_config SET worker_hash=?,last_seen=NULL WHERE agent_id=? AND org_id=?",hash(secret),id,org());return Map.of("agentId",id,"coreUrl","http://127.0.0.1:8080","workerId","local-"+id,"credential",secret,"configFile","~/.config/professy/local-agent.json");}
 public static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 boolean operator(){return access.admin(access.actor())||access.policy.can(access.actor(),"PROJECTS.UPDATE");}
 Map<String,Object> supportRow(long id){var rows=access.jdbc.queryForList("SELECT * FROM delivery_support WHERE id=? AND org_id=?",id,org());if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Support request not found");var row=rows.getFirst();access.project(number(row.get("project_id")));if(!operator()&&number(row.get("requester_id"))!=access.actor().getId())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"This support request is private");return row;}
 @GetMapping("/support") public Object support(@RequestParam long projectId,@RequestParam(defaultValue="0")long before){access.project(projectId);return access.jdbc.queryForList("SELECT s.*,v.name AS serviceName,a.display_name AS agentName,j.id AS jobId,j.state AS jobState,j.updated_at AS runUpdatedAt FROM delivery_support s JOIN delivery_services v ON v.id=s.service_id LEFT JOIN workspace_actors a ON a.id=s.agent_id LEFT JOIN delivery_jobs j ON j.id=(SELECT latest.id FROM delivery_jobs latest WHERE latest.support_id=s.id ORDER BY latest.created_at DESC LIMIT 1) WHERE s.org_id=? AND s.project_id=? AND (? OR s.requester_id=?) AND (?=0 OR s.id<?) ORDER BY s.id DESC LIMIT 40",org(),projectId,operator(),access.actor().getId(),before,before);}
 @PostMapping("/support") @Transactional public Object raise(@RequestBody Map<String,Object>b){var service=service(number(b.get("serviceId")));long project=number(service.get("project_id"));String title=required(b.get("title"),255),description=required(b.get("description"),12000),priority=choice(b.getOrDefault("priority","MEDIUM"),Set.of("LOW","MEDIUM","HIGH","CRITICAL")),workflow=choice(b.getOrDefault("workflow","python-prototype"),Set.of("python-prototype","priority-normalizer-v1"));
  var issue=new Issues();issue.setOrgId(org());issue.setProject(projects.findById(project).orElseThrow());issue.setUser(access.actor());issue.setCreator(access.actor());issue.setReporter(access.actor());issue.setTitle(title);issue.setDescription(description);issue.setIssueCode("SUP-"+UUID.randomUUID().toString().substring(0,18));issue.setStatus("BACKLOG");issues.saveAndFlush(issue);
  long id=insert("INSERT INTO delivery_support(org_id,project_id,service_id,issue_id,requester_id,title,description,priority,workflow) VALUES(?,?,?,?,?,?,?,?,?)",org(),project,service.get("id"),issue.getId(),access.actor().getId(),title,description,priority,workflow);
  access.jdbc.update("INSERT IGNORE INTO ticket_watchers(org_id,project_id,ticket_type,ticket_id,user_id) VALUES(?,?,'ISSUE',?,?)",org(),project,issue.getId(),access.actor().getId());
  if(Boolean.TRUE.equals(b.get("automatic"))){var candidates=access.jdbc.queryForList("SELECT c.agent_id FROM delivery_agent_config c JOIN workspace_actors a ON a.id=c.agent_id JOIN workspace_agent_projects p ON p.actor_id=a.id WHERE c.org_id=? AND c.enabled=1 AND c.worker_hash IS NOT NULL AND a.status='ACTIVE' AND p.project_id=? ORDER BY c.last_seen DESC,c.agent_id LIMIT 1",org(),project);if(!candidates.isEmpty())dispatch(id,Map.of("agentId",candidates.getFirst().get("agent_id")));}
  return supportRow(id);}
 @PostMapping("/support/{id}/dispatch") @Transactional public Object dispatch(@PathVariable long id,@RequestBody Map<String,Object>b){var support=supportRow(id);if(!operator()&&number(support.get("requester_id"))!=access.actor().getId())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Request access denied");if(!Set.of("OPEN","FAILED").contains(support.get("state")))throw new ResponseStatusException(HttpStatus.CONFLICT,"This request already has a run");long agent=number(b.get("agentId"));var a=agents.row(agent);if(!"ACTIVE".equals(a.get("status"))||!agents.projects(agent).contains(number(support.get("project_id"))))throw new IllegalArgumentException("Choose an active project agent");var configs=access.jdbc.queryForList("SELECT * FROM delivery_agent_config WHERE agent_id=? AND org_id=? AND enabled=1 AND worker_hash IS NOT NULL",agent,org());if(configs.isEmpty())throw new IllegalArgumentException("Configure and enroll this agent's worker first");var effective=(Map<?,?>)((Map<?,?>)agents.permissions(agent)).get("effective");if(!Boolean.TRUE.equals(effective.get("TICKETS.READ"))||!Boolean.TRUE.equals(effective.get("TICKETS.UPDATE")))throw new IllegalArgumentException("Agent needs ticket read and update permissions");
  // Serialize dispatches for this case; no human token is retained by the queue.
  var locked=access.jdbc.queryForList("SELECT state FROM delivery_support WHERE id=? FOR UPDATE",id);if(locked.isEmpty()||!Set.of("OPEN","FAILED").contains(locked.getFirst().get("state")))throw new ResponseStatusException(HttpStatus.CONFLICT,"This request already has a run");if(access.jdbc.queryForObject("SELECT COUNT(*) FROM delivery_jobs WHERE support_id=? AND state IN ('QUEUED','RUNNING','REVIEW_READY')",Integer.class,id)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Run already exists");
  String job=UUID.randomUUID().toString().replace("-","");access.jdbc.update("INSERT INTO delivery_jobs(id,org_id,project_id,support_id,ticket_kind,ticket_id,service_id,agent_id,requested_by,title,instructions,workflow) VALUES(?,?,?,?,'ISSUE',?,?,?,?,?,?,?)",job,org(),support.get("project_id"),id,support.get("issue_id"),support.get("service_id"),agent,access.actor().getId(),support.get("title"),support.get("description"),support.get("workflow"));access.jdbc.update("UPDATE delivery_support SET agent_id=?,state='QUEUED',updated_at=CURRENT_TIMESTAMP(6) WHERE id=?",agent,id);
  access.jdbc.update("DELETE FROM ticket_actor_assignments WHERE org_id=? AND ticket_type='ISSUE' AND ticket_id=? AND assignment_role='ASSIGNEE'",org(),support.get("issue_id"));access.jdbc.update("UPDATE issues SET assignee_user_id=NULL WHERE id=? AND org_id=?",support.get("issue_id"),org());access.jdbc.update("INSERT INTO ticket_actor_assignments(org_id,project_id,ticket_type,ticket_id,assignment_role,actor_id,updated_by) VALUES(?,?,'ISSUE',?,'ASSIGNEE',?,?)",org(),support.get("project_id"),support.get("issue_id"),agent,access.actor().getId());return Map.of("id",job,"state","QUEUED");}
 @PostMapping("/support/{id}/take-ownership") @Transactional public Object takeOwnership(@PathVariable long id){access.require("TICKETS.UPDATE");var row=supportRow(id);access.jdbc.queryForList("SELECT id FROM delivery_support WHERE id=? FOR UPDATE",id);access.jdbc.update("UPDATE delivery_jobs SET state='CANCELLED',lease_until=NULL,updated_at=CURRENT_TIMESTAMP(6) WHERE support_id=? AND state IN ('QUEUED','RUNNING','REVIEW_READY')",id);access.jdbc.update("DELETE FROM ticket_actor_assignments WHERE org_id=? AND ticket_type='ISSUE' AND ticket_id=? AND assignment_role='ASSIGNEE'",org(),row.get("issue_id"));access.jdbc.update("UPDATE issues SET assignee_user_id=?,status='TODO' WHERE id=? AND org_id=?",access.actor().getId(),row.get("issue_id"),org());access.jdbc.update("UPDATE delivery_support SET agent_id=NULL,state='OPEN',updated_at=CURRENT_TIMESTAMP(6) WHERE id=?",id);return supportRow(id);}
 @GetMapping("/jobs") public Object jobs(@RequestParam long projectId){access.project(projectId);return access.jdbc.queryForList("SELECT j.id,j.title,j.state,j.support_id,j.ticket_kind,j.ticket_id,j.project_id,j.agent_id,a.display_name AS agentName,j.created_at,j.updated_at,j.attachment_id,j.result_json FROM delivery_jobs j JOIN workspace_actors a ON a.id=j.agent_id WHERE j.org_id=? AND j.project_id=? AND (? OR j.requested_by=?) ORDER BY j.created_at DESC LIMIT 60",org(),projectId,operator(),access.actor().getId()).stream().map(row->{if(row.get("result_json")!=null)row.put("result",json.readValue(row.remove("result_json").toString(),Map.class));return row;}).toList();}
 @PostMapping("/jobs/{id}/release") @Transactional public Object release(@PathVariable String id,@RequestBody Map<String,Object>b){access.require("RELEASES.CREATE");manage();var rows=access.jdbc.queryForList("SELECT * FROM delivery_jobs WHERE id=? AND org_id=? FOR UPDATE",id,org());if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Run not found");var job=rows.getFirst();access.project(number(job.get("project_id")));var existing=access.jdbc.queryForList("SELECT release_id FROM delivery_release_services WHERE job_id=? AND org_id=? FOR UPDATE",id,org());if(!existing.isEmpty())return Map.of("releaseId",existing.getFirst().get("release_id"));if(!"REVIEW_READY".equals(job.get("state")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Passing evidence must be reviewed before preparing a release");long sprint=number(b.get("sprintId"));if(access.jdbc.queryForObject("SELECT COUNT(*) FROM sprints WHERE id=? AND org_id=? AND project_id=?",Integer.class,sprint,org(),job.get("project_id"))!=1)throw new IllegalArgumentException("Choose a sprint in this project");var r=new Releases();r.setOrgId(org());r.setProjectId(number(job.get("project_id")));r.setSprintId(sprint);r.setUserId(access.actor().getId());r.setAssigneeId(access.actor().getId());r.setName(required(b.get("name"),191));r.setVersionNumber(required(b.get("version"),50));r.setStatus(Releases.Status.PLANNED);r.setNotes("Reviewed local prototype. Agent "+job.get("agent_id")+"; run "+id+". Evidence attached to "+job.get("ticket_kind")+"-"+job.get("ticket_id")+". This release is a plan, not a deployment.");releases.saveAndFlush(r);access.jdbc.update("INSERT INTO delivery_release_services(release_id,service_id,job_id,org_id) VALUES(?,?,?,?)",r.getId(),job.get("service_id"),id,org());access.jdbc.update("INSERT INTO release_items(org_id,release_id,sprint_id,work_item_id,item_type,included_at) VALUES(?,?,?,?,?,CURRENT_TIMESTAMP(6))",org(),r.getId(),sprint,job.get("ticket_id"),"ISSUE".equals(job.get("ticket_kind"))?"BUG":job.get("ticket_kind"));access.jdbc.update("UPDATE issues SET status='COMPLETED' WHERE id=? AND org_id=?",job.get("ticket_id"),org());access.jdbc.update("UPDATE delivery_jobs SET state='APPROVED',updated_at=CURRENT_TIMESTAMP(6) WHERE id=?",id);if(job.get("support_id")!=null)access.jdbc.update("UPDATE delivery_support SET state='RESOLVED',updated_at=CURRENT_TIMESTAMP(6) WHERE id=?",job.get("support_id"));return Map.of("releaseId",r.getId(),"state","PLANNED");}
 @GetMapping("/releases") public Object linkedReleases(@RequestParam long projectId){access.project(projectId);return access.jdbc.queryForList("SELECT r.id,r.name,r.version_number,r.status,r.release_date,s.name AS serviceName,l.service_id,l.job_id FROM delivery_release_services l JOIN releases r ON r.id=l.release_id JOIN delivery_services s ON s.id=l.service_id WHERE l.org_id=? AND r.project_id=? ORDER BY r.created_at DESC LIMIT 100",org(),projectId);}
}
